insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp10-10-vvti','Toyota','Yaris','XP10 (_P1_)','1.0 VVT-i 68 CV',1999,2005,'1SZ-FE','Yaris XP10, 1999–2005 · motor 1SZ-FE 998 cc, 68 CV · gasolina','gasolina',50,'[["Motor", "1SZ-FE, 4 cilindros, 998 cc, 50 kW (68 CV)"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "5W-30 (API SJ/SL) · unos 3,2 L con filtro"], ["Cambio", "Manual de 5 o MultiMode (manual robotizado)"], ["Neumáticos", "155/80 R13 o 175/65 R14 según acabado (mira el flanco de los tuyos)"], ["Bujías", "4 unidades, de iridio o platino (tipo exacto: compruébalo por matrícula)"], ["Frenos", "Delante disco ventilado; detrás tambor"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Long Life Coolant (rojo) o Super Long Life Coolant (rosa) según año: mira el color del depósito"]]'::jsonb);
