insert into model_sources (model_id,title,url) values ('toyota-yaris-xp10-10-vvti','Motor1 Italia: historia de los motores del Toyota Yaris','https://it.motor1.com/news/658563/toyota-yaris-motori-storia/');
insert into model_sources (model_id,title,url) values ('toyota-yaris-xp10-10-vvti','Wikipedia: motores Toyota SZ (1SZ-FE, 2SZ-FE), distribución por cadena','https://en.wikipedia.org/wiki/Toyota_SZ_engine');
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','aceite','Aceite de motor y filtro','Cambiar',15000,12,null,false,'fabricante','Plan Toyota','Toyota indica una revisión al año o cada 15.000 km (10.000 millas en el Reino Unido) para todos los Yaris, también el primero. Se cambian aceite y filtro en cada revisión.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Plazo habitual en los planes europeos de este Yaris (idgarages lo incluye en la revisión de 60.000 km / 4 años). No pude leer el plan original de Toyota.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','bujias','Bujías','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Son 4 bujías. Los planes publicados para el Yaris de 1999–2005 las cambian en la revisión de 60.000 km / 4 años; no pude leer el plan original de Toyota.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','frenos-liquido','Líquido de frenos','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Toyota lo cambia cada 2 años en todos sus planes europeos; para este Yaris solo lo he visto en planes de terceros (idgarages). En los manuales el embrague usa el mismo líquido.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','refrigerante','Líquido refrigerante','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Depende del refrigerante que lleve: el rojo normal se cambia hacia los 4 años; si es rosa (Super Long Life), el primer cambio es a los 150.000 km. No pude leer el plan Toyota de esta generación; los planes de terceros dan entre 3 y 4 años.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Se miran en cada revisión. Cambiar pastillas con menos de 3 mm de material.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor. Revisar desgaste y ajuste del freno de mano.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','correa','Correa de accesorios: revisar','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar grietas y tensión; cambiar si está agrietada o chirría. No pude confirmar el plazo de Toyota para esta generación.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor 1SZ-FE lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','valvulas','Holgura de válvulas','Revisar si hace ruido',null,null,null,true,'aproximado','Plazo aproximado','Sin ajuste programado conocido: Toyota en esta época solo pedía escuchar si hay ruido de taqués. No pude leer el plan de esta generación.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','filtro-gasolina','Filtro de gasolina','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Va dentro del depósito junto a la bomba y el plan Toyota del Yaris no lo cambia. Solo se toca si falla la bomba.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar nivel y fugas cada 4 años; el plan británico de Toyota lo pone a los 4 años / 40.000 millas. No pude confirmar si pide cambiarlo.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','embrague','Embrague: revisar pedal','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Comprobar juego del pedal y que no patine. El embrague es hidráulico y comparte líquido con los frenos.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',17);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-10-vvti','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',18);
