insert into model_sources (model_id,title,url) values ('toyota-yaris-xp10-13-vvti-2sz','Wikipedia: motores Toyota SZ (1SZ-FE, 2SZ-FE), distribución por cadena','https://en.wikipedia.org/wiki/Toyota_SZ_engine');
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','aceite','Aceite de motor y filtro','Cambiar',15000,12,null,false,'fabricante','Plan Toyota','Toyota indica una revisión al año o cada 15.000 km (10.000 millas en el Reino Unido) para todos los Yaris, también el primero. Se cambian aceite y filtro en cada revisión.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Plazo habitual en los planes europeos de este Yaris (idgarages lo incluye en la revisión de 60.000 km / 4 años). No pude leer el plan original de Toyota.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','bujias','Bujías','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Son 4 bujías. Los planes publicados para el Yaris de 1999–2005 las cambian en la revisión de 60.000 km / 4 años; no pude leer el plan original de Toyota.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','frenos-liquido','Líquido de frenos','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Toyota lo cambia cada 2 años en todos sus planes europeos; para este Yaris solo lo he visto en planes de terceros (idgarages). En los manuales el embrague usa el mismo líquido.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','refrigerante','Líquido refrigerante','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Depende del refrigerante que lleve: el rojo normal se cambia hacia los 4 años; si es rosa (Super Long Life), el primer cambio es a los 150.000 km. No pude leer el plan Toyota de esta generación; los planes de terceros dan entre 3 y 4 años.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Se miran en cada revisión. Cambiar pastillas con menos de 3 mm de material.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor. Revisar desgaste y ajuste del freno de mano.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','correa','Correa de accesorios: revisar','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar grietas y tensión; cambiar si está agrietada o chirría. No pude confirmar el plazo de Toyota para esta generación.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor 2SZ-FE lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','valvulas','Holgura de válvulas','Revisar si hace ruido',null,null,null,true,'aproximado','Plazo aproximado','Sin ajuste programado conocido: Toyota en esta época solo pedía escuchar si hay ruido de taqués. No pude leer el plan de esta generación.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','filtro-gasolina','Filtro de gasolina','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Va dentro del depósito junto a la bomba y el plan Toyota del Yaris no lo cambia. Solo se toca si falla la bomba.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar nivel y fugas cada 4 años; el plan británico de Toyota lo pone a los 4 años / 40.000 millas. No pude confirmar si pide cambiarlo.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','embrague','Embrague: revisar pedal','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Comprobar juego del pedal y que no patine. El embrague es hidráulico y comparte líquido con los frenos.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',17);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-13-vvti-2sz','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',18);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp10-15-vvti-ts','Toyota','Yaris','XP10 (_P1_)','1.5 VVT-i TS 106 CV',2001,2005,'1NZ-FE','Yaris XP10, 2001–2005 · motor 1NZ-FE 1497 cc, 106 CV · gasolina','gasolina',78,'[["Motor", "1NZ-FE, 4 cilindros, 1497 cc, 78 kW (106 CV)"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "5W-30 (API SJ/SL) · unos 3,7 L con filtro"], ["Cambio", "Manual de 5"], ["Neumáticos", "195/50 R15 o 185/55 R15 según año (mira el flanco de los tuyos)"], ["Bujías", "4 unidades, de iridio o platino (tipo exacto: compruébalo por matrícula)"], ["Frenos", "Delante disco ventilado; detrás disco o tambor según año: comprobar"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Long Life Coolant (rojo) o Super Long Life Coolant (rosa) según año: mira el color del depósito"]]'::jsonb);
