insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor. Revisar desgaste y ajuste del freno de mano.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','correa','Correa de accesorios: revisar','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar grietas y tensión; cambiar si está agrietada o chirría. No pude confirmar el plazo de Toyota para esta generación.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor 1ND-TV lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','filtro-gasoil','Filtro de gasoil','Cambiar',90000,72,null,false,'aproximado','Plazo aproximado','Planes de terceros (idgarages) lo cambian a los 90.000 km o 6 años, igual que las tablas de Toyota del modelo siguiente. Purga el agua si se enciende el testigo.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar nivel y fugas cada 4 años; el plan británico de Toyota lo pone a los 4 años / 40.000 millas. No pude confirmar si pide cambiarlo.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','embrague','Embrague: revisar pedal','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Comprobar juego del pedal y que no patine. El embrague es hidráulico y comparte líquido con los frenos.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp10-14-d4d','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',16);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp90-10-vvti','Toyota','Yaris','XP90 (_P9_)','1.0 VVT-i 69 CV',2005,2011,'1KR-FE','Yaris XP90, 2005–2011 · motor 1KR-FE 998 cc, 69 CV · gasolina','gasolina',51,'[["Motor", "1KR-FE, 3 cilindros, 998 cc, 51 kW (69 CV)"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "5W-30 (API SL/SM o ILSAC) · unos 3,1 L con filtro"], ["Cambio", "Manual de 5 o MultiMode"], ["Neumáticos", "175/65 R14 (mira el flanco de los tuyos)"], ["Bujías", "3 unidades, de iridio o platino (tipo exacto: compruébalo por matrícula)"], ["Frenos", "Delante disco ventilado; detrás tambor"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Super Long Life Coolant (rosa), ya mezclado"]]'::jsonb);
insert into model_sources (model_id,title,url) values ('toyota-yaris-xp90-10-vvti','Toyota Europe: programa de mantenimiento Yaris XP90 (KSP90/SCP90/NSP90/ZSP90/NLP90), servicio cada 15.000 km','https://www.gerritspeek.nl/auto/diversen/yaris_maintenance_schedule.pdf');
