insert into model_sources (model_id,title,url) values ('toyota-yaris-xp90-10-vvti','Toyota Owners Club: códigos de motor del Yaris por generación','https://toyotaownersclub.com/forums/topic/95047-yaris-engine-codes');
insert into model_sources (model_id,title,url) values ('toyota-yaris-xp90-10-vvti','Motor1 Italia: historia de los motores del Toyota Yaris','https://it.motor1.com/news/658563/toyota-yaris-motori-storia/');
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','aceite','Aceite de motor y filtro','Cambiar',15000,12,null,false,'fabricante','Plan Toyota','Plan Toyota Europa: aceite y filtro cada 15.000 km o 12 meses, lo que llegue antes. Si haces trayectos muy cortos, remolque o caminos de tierra, Toyota pide cambiarlo cada 6 meses.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','filtro-aire','Filtro de aire del motor','Cambiar',45000,48,null,false,'aproximado','Plazo aproximado','La tabla europea de Toyota para el XP90 parece decir cambio cada 45.000 km o 48 meses, pero no pude leerla con seguridad. Se revisa en cada servicio; con polvo, antes.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','bujias','Bujías','Cambiar',90000,72,null,false,'aproximado','Plazo aproximado','Son 3 bujías de iridio. El libro de servicio británico dice 6 años o 60.000 millas y el del Yaris actual 90.000 km; la tabla europea de esta generación no se pudo leer bien. Si quieres ir sobre seguro, cámbialas a los 60.000 km.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','frenos-liquido','Líquido de frenos','Cambiar',30000,24,null,false,'fabricante','Plan Toyota','Plan Toyota: cambiar cada 2 años o 30.000 km. Absorbe humedad con el tiempo, así que hazlo aunque uses poco el coche. En los manuales el embrague hidráulico usa el mismo líquido.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','refrigerante','Líquido refrigerante','Cambiar',150000,120,null,false,'fabricante','Plan Toyota','Plan Toyota con refrigerante Super Long Life (rosa): primer cambio a los 150.000 km (o 10 años) y después cada 90.000 km. Revisar nivel en cada servicio.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Se miran en cada revisión. Cambiar pastillas con menos de 3 mm de material.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor. Revisar desgaste y ajuste del freno de mano.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','correa','Correa de accesorios: revisar','Revisar',105000,72,null,false,'fabricante','Plan Toyota','Plan Toyota: primera revisión a los 6 años (el libro del Yaris actual dice 6 años o 105.000 km) y después en cada revisión anual. Se cambia solo si tiene grietas o chirría.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor 1KR-FE lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','valvulas','Holgura de válvulas','Revisar si hace ruido',null,null,null,true,'fabricante','Plan Toyota','Toyota solo pide escuchar si hay ruido de taqués o vibraciones en cada revisión y ajustar si hace falta. No hay ajuste programado.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','filtro-gasolina','Filtro de gasolina','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Va dentro del depósito junto a la bomba y el plan Toyota del Yaris no lo cambia. Solo se toca si falla la bomba.',11);
