insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-10-vvti','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',18);
