insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-13-vvti','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar nivel y fugas cada 4 años; el plan británico de Toyota lo pone a los 4 años / 40.000 millas. No pude confirmar si pide cambiarlo.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-13-vvti','embrague','Embrague: revisar pedal','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Comprobar juego del pedal y que no patine. El embrague es hidráulico y comparte líquido con los frenos.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-13-vvti','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-13-vvti','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-13-vvti','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-13-vvti','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',17);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-13-vvti','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',18);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp90-133-dual-vvti','Toyota','Yaris','XP90 (_P9_)','1.33 Dual VVT-i 101 CV',2008,2011,'1NR-FE','Yaris XP90, 2008–2011 · motor 1NR-FE 1329 cc, 101 CV · gasolina','gasolina',74,'[["Motor", "1NR-FE, 4 cilindros, 1329 cc, 74 kW (101 CV)"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "0W-20 (ILSAC GF-4/GF-5) · unos 3,4 L con filtro"], ["Cambio", "Manual de 6 o MultiMode"], ["Neumáticos", "175/65 R14 o 185/60 R15 (mira el flanco de los tuyos)"], ["Bujías", "4 unidades, de iridio o platino (tipo exacto: compruébalo por matrícula)"], ["Frenos", "Delante disco ventilado; detrás tambor"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Super Long Life Coolant (rosa), ya mezclado"]]'::jsonb);
