insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-18-vvti-ts','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-18-vvti-ts','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',17);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp90-18-vvti-ts','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',18);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp90-14-d4d','Toyota','Yaris','XP90 (_P9_)','1.4 D-4D 90 CV',2005,2011,'1ND-TV','Yaris XP90, 2005–2011 · motor 1ND-TV 1364 cc, 90 CV · diésel','diesel',66,'[["Motor", "1ND-TV, 4 cilindros, 1364 cc, 66 kW (90 CV)"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "5W-30 para diésel (ACEA B1/B3/B4; C2 si lleva filtro de partículas) · 4,2–4,3 L con filtro"], ["Cambio", "Manual de 6 o MultiMode"], ["Neumáticos", "175/65 R14 o 185/60 R15 (mira el flanco de los tuyos)"], ["Calentadores", "4 calentadores; sin cambio programado"], ["Frenos", "Delante disco ventilado; detrás tambor"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Super Long Life Coolant (rosa), ya mezclado"]]'::jsonb);
