insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-10-vvti','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-10-vvti','bujias','Bujías','Cambiar',90000,72,null,false,'aproximado','Plazo aproximado','Son 3 bujías de iridio. El libro de servicio británico dice 6 años o 60.000 millas y el del Yaris actual 90.000 km; la tabla europea de esta generación no se pudo leer bien. Si quieres ir sobre seguro, cámbialas a los 60.000 km.',3);
