insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-10-vvti','valvulas','Holgura de válvulas','Revisar si hace ruido',null,null,null,true,'fabricante','Plan Toyota','Toyota solo pide escuchar si hay ruido de taqués o vibraciones en cada revisión y ajustar si hace falta. No hay ajuste programado.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-10-vvti','filtro-gasolina','Filtro de gasolina','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Va dentro del depósito junto a la bomba y el plan Toyota del Yaris no lo cambia. Solo se toca si falla la bomba.',11);
