insert into model_sources (model_id,title,url) values ('toyota-yaris-xp130-133-dual-vvti','Motor1 Italia: historia de los motores del Toyota Yaris','https://it.motor1.com/news/658563/toyota-yaris-motori-storia/');
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','aceite','Aceite de motor y filtro','Cambiar',15000,12,null,false,'fabricante','Plan Toyota','Plan Toyota Europa: aceite y filtro cada 15.000 km o 12 meses, lo que llegue antes. Si haces trayectos muy cortos, remolque o caminos de tierra, Toyota pide cambiarlo cada 6 meses.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Plazo tomado del libro del Yaris actual (60.000 km o 4 años); la tabla Toyota de esta generación no se pudo leer con seguridad. Se revisa en cada servicio.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','bujias','Bujías','Cambiar',90000,72,null,false,'aproximado','Plazo aproximado','Son 4 bujías de iridio. El libro de servicio británico dice 6 años o 60.000 millas y el del Yaris actual 90.000 km; la tabla europea de esta generación no se pudo leer bien. Si quieres ir sobre seguro, cámbialas a los 60.000 km.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','frenos-liquido','Líquido de frenos','Cambiar',30000,24,null,false,'fabricante','Plan Toyota','Plan Toyota: cambiar cada 2 años o 30.000 km. Absorbe humedad con el tiempo, así que hazlo aunque uses poco el coche. En los manuales el embrague hidráulico usa el mismo líquido.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','refrigerante','Líquido refrigerante','Cambiar',150000,120,null,false,'fabricante','Plan Toyota','Plan Toyota con refrigerante Super Long Life (rosa): primer cambio a los 150.000 km (o 10 años) y después cada 90.000 km. Revisar nivel en cada servicio.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Se miran en cada revisión. Cambiar pastillas con menos de 3 mm de material.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor. Revisar desgaste y ajuste del freno de mano.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','correa','Correa de accesorios: revisar','Revisar',105000,72,null,false,'fabricante','Plan Toyota','Plan Toyota: primera revisión a los 6 años (el libro del Yaris actual dice 6 años o 105.000 km) y después en cada revisión anual. Se cambia solo si tiene grietas o chirría.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor 1NR-FE lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','valvulas','Holgura de válvulas','Revisar si hace ruido',null,null,null,true,'fabricante','Plan Toyota','Toyota solo pide escuchar si hay ruido de taqués o vibraciones en cada revisión y ajustar si hace falta. No hay ajuste programado.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','filtro-gasolina','Filtro de gasolina','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Va dentro del depósito junto a la bomba y el plan Toyota del Yaris no lo cambia. Solo se toca si falla la bomba.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Manual: revisar nivel cada 4 años (el plan británico de Toyota lo pone a los 4 años / 40.000 millas). En el CVT Multidrive S se usa aceite Toyota CVT Fluid TC y se revisa; no pude leer cuándo lo cambia Toyota.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','embrague','Embrague: revisar pedal','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Comprobar juego del pedal y que no patine. El embrague es hidráulico y comparte líquido con los frenos.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',17);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-133-dual-vvti','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',18);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp130-15-dual-vvtie','Toyota','Yaris','XP130 (_P13_)','1.5 Dual VVT-iE 111 CV',2017,2020,'2NR-FKE','Yaris XP130, 2017–2020 · motor 2NR-FKE 1496 cc, 111 CV · gasolina','gasolina',82,'[["Motor", "2NR-FKE, 4 cilindros, 1496 cc, 82 kW (111 CV)"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "0W-20 (ILSAC GF-5) · capacidad sin confirmar (unos 3,5 L)"], ["Cambio", "Manual de 6 o CVT Multidrive S"], ["Neumáticos", "185/60 R15 o 195/50 R16 (mira el flanco de los tuyos)"], ["Bujías", "4 unidades, de iridio o platino (tipo exacto: compruébalo por matrícula)"], ["Frenos", "Delante disco ventilado; detrás tambor"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Super Long Life Coolant (rosa), ya mezclado"]]'::jsonb);
