insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','bujias','Bujías','Cambiar',90000,72,null,false,'aproximado','Plazo aproximado','Son 4 bujías de iridio. El libro de servicio británico dice 6 años o 60.000 millas y el del Yaris actual 90.000 km; la tabla europea de esta generación no se pudo leer bien. Si quieres ir sobre seguro, cámbialas a los 60.000 km.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','frenos-liquido','Líquido de frenos','Cambiar',30000,24,null,false,'fabricante','Plan Toyota','Plan Toyota: cambiar cada 2 años o 30.000 km. Absorbe humedad con el tiempo, así que hazlo aunque uses poco el coche.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','refrigerante','Líquido refrigerante','Cambiar',150000,120,null,false,'fabricante','Plan Toyota','Plan Toyota con refrigerante Super Long Life (rosa): primer cambio a los 150.000 km (o 10 años) y después cada 90.000 km. Revisar nivel en cada servicio. El sistema híbrido tiene además un circuito para el inversor con el mismo líquido.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Se miran en cada revisión. Cambiar pastillas con menos de 3 mm de material. En el híbrido duran mucho más porque frena el motor eléctrico; vigila que los discos no se oxiden.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor o disco según acabado. Revisar desgaste y ajuste del freno de mano.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor 1NZ-FXE lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','valvulas','Holgura de válvulas','Revisar si hace ruido',null,null,null,true,'fabricante','Plan Toyota','Toyota solo pide escuchar si hay ruido de taqués o vibraciones en cada revisión y ajustar si hace falta. No hay ajuste programado.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','filtro-gasolina','Filtro de gasolina','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Va dentro del depósito junto a la bomba y el plan Toyota del Yaris no lo cambia. Solo se toca si falla la bomba.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','caja-cambios','Aceite de la transmisión híbrida','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','La transmisión híbrida no tiene embrague ni cambio de aceite programado conocido; que revisen nivel y fugas cada pocos años. Usa aceite Toyota WS.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','filtro-bateria-hibrida','Filtro del ventilador de la batería híbrida','Limpiar',15000,12,null,false,'aproximado','Plazo aproximado','La toma de aire de la batería híbrida está junto al asiento trasero. Límpiala en cada revisión, más a menudo si llevas perro o mucho polvo: si se tapa, la batería se calienta.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años. En el híbrido la batería de 12 V es pequeña: si se descarga, el coche no se pone en READY aunque la batería híbrida esté bien.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-15-hybrid','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',17);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp130-14-d4d','Toyota','Yaris','XP130 (_P13_)','1.4 D-4D 90 CV',2011,2018,'1ND-TV','Yaris XP130, 2011–2018 · motor 1ND-TV 1364 cc, 90 CV · diésel','diesel',66,'[["Motor", "1ND-TV, 4 cilindros, 1364 cc, 66 kW (90 CV)"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "5W-30 o 0W-30 bajo en cenizas (ACEA C2) por el filtro de partículas · unos 3,9 L con filtro"], ["Cambio", "Manual de 6"], ["Neumáticos", "175/65 R15 o 185/60 R15 (mira el flanco de los tuyos)"], ["Calentadores", "4 calentadores; sin cambio programado"], ["Frenos", "Delante disco ventilado; detrás tambor"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Super Long Life Coolant (rosa), ya mezclado"]]'::jsonb);
