insert into model_sources (model_id,title,url) values ('toyota-yaris-xp130-14-d4d','Motor1 Italia: historia de los motores del Toyota Yaris','https://it.motor1.com/news/658563/toyota-yaris-motori-storia/');
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','aceite','Aceite de motor y filtro','Cambiar',15000,12,null,false,'fabricante','Plan Toyota','Plan Toyota Europa: aceite y filtro cada 15.000 km o 12 meses, lo que llegue antes. Si haces trayectos muy cortos, remolque o caminos de tierra, Toyota pide cambiarlo cada 6 meses.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Plazo tomado del libro del Yaris actual (60.000 km o 4 años); la tabla Toyota de esta generación no se pudo leer con seguridad. Se revisa en cada servicio.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','frenos-liquido','Líquido de frenos','Cambiar',30000,24,null,false,'fabricante','Plan Toyota','Plan Toyota: cambiar cada 2 años o 30.000 km. Absorbe humedad con el tiempo, así que hazlo aunque uses poco el coche. En los manuales el embrague hidráulico usa el mismo líquido.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','refrigerante','Líquido refrigerante','Cambiar',150000,120,null,false,'fabricante','Plan Toyota','Plan Toyota con refrigerante Super Long Life (rosa): primer cambio a los 150.000 km (o 10 años) y después cada 90.000 km. Revisar nivel en cada servicio.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Se miran en cada revisión. Cambiar pastillas con menos de 3 mm de material.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor. Revisar desgaste y ajuste del freno de mano.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','correa','Correa de accesorios: revisar','Revisar',105000,72,null,false,'fabricante','Plan Toyota','Plan Toyota: primera revisión a los 6 años (el libro del Yaris actual dice 6 años o 105.000 km) y después en cada revisión anual. Se cambia solo si tiene grietas o chirría.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor 1ND-TV lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','filtro-gasoil','Filtro de gasoil','Cambiar',90000,72,null,false,'aproximado','Plazo aproximado','La tabla de Toyota marca el cambio a los 72 meses (6 años); los 90.000 km salen de planes de terceros (idgarages). Purga el agua del filtro si se enciende el testigo.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar nivel y fugas cada 4 años; el plan británico de Toyota lo pone a los 4 años / 40.000 millas. No pude confirmar si pide cambiarlo.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','embrague','Embrague: revisar pedal','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Comprobar juego del pedal y que no patine. El embrague es hidráulico y comparte líquido con los frenos.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp130-14-d4d','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',16);
