insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-125','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Revisar nivel y fugas cada 4 años; el plan británico de Toyota lo pone a los 4 años / 40.000 millas. No pude confirmar si pide cambiarlo.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-125','embrague','Embrague: revisar pedal','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Comprobar juego del pedal y que no patine. El embrague es hidráulico y comparte líquido con los frenos.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-125','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-125','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-125','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-125','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años.',17);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-125','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',18);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('toyota-yaris-xp210-15-hybrid-116','Toyota','Yaris','XP210 (_P21_, _PA1_, _PH1_)','1.5 Hybrid 116 CV',2020,null,'M15A-FXE','Yaris XP210, desde 2020 · motor M15A-FXE 1490 cc, 116 CV · híbrido gasolina-eléctrico','hibrido',85,'[["Motor", "M15A-FXE, 3 cilindros, 1490 cc, 85 kW (116 CV) de potencia conjunta del sistema híbrido"], ["Distribución", "Por cadena: sin cambio programado. Si hace ruido metálico al arrancar en frío, que lo mire un taller."], ["Aceite motor", "0W-8 de fábrica (Toyota admite 0W-16/0W-20) · capacidad sin confirmar"], ["Cambio", "Transmisión híbrida e-CVT (sin embrague)"], ["Neumáticos", "185/65 R15, 195/55 R16 o 205/45 R17 según acabado (mira el flanco de los tuyos)"], ["Bujías", "3 unidades, de iridio o platino (tipo exacto: compruébalo por matrícula)"], ["Frenos", "Delante disco ventilado; detrás tambor o disco según acabado"], ["Líquido de frenos", "DOT 3 o DOT 4 (SAE J1703/J1704)"], ["Refrigerante", "Toyota Super Long Life Coolant (rosa), ya mezclado"], ["Sistema híbrido", "Batería de alta tensión bajo el asiento trasero con ventilador y filtro de aire propios; batería auxiliar de 12 V pequeña"]]'::jsonb);
insert into model_sources (model_id,title,url) values ('toyota-yaris-xp210-15-hybrid-116','Club Toyota Yaris España: intervalos copiados del libro de mantenimiento (Yaris 2024 1.5 125 CV)','https://www.clubtoyotayaris.es/threads/periodos-de-mantenimiento-acertados.3818/');
insert into model_sources (model_id,title,url) values ('toyota-yaris-xp210-15-hybrid-116','Toyota UK: intervalos de servicio del Yaris, todas las generaciones (anual / 10.000 millas)','https://mag.toyota.co.uk/find-out-when-your-toyota-yaris-needs-a-service-whatever-its-age/comment-page-1/');
insert into model_sources (model_id,title,url) values ('toyota-yaris-xp210-15-hybrid-116','Toyota Owners Club: aceite 0W-8 en el Yaris Hybrid 2020+ (primera revisión)','https://www.toyotaownersclub.com/forums/topic/212082-first-service/');
insert into model_sources (model_id,title,url) values ('toyota-yaris-xp210-15-hybrid-116','Wikipedia: Toyota Yaris (XP210), motores europeos','https://en.wikipedia.org/wiki/Toyota_Yaris_(XP210)');
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','aceite','Aceite de motor y filtro','Cambiar',15000,12,null,false,'fabricante','Plan Toyota','Plan Toyota Europa: aceite y filtro cada 15.000 km o 12 meses, lo que llegue antes. Si haces trayectos muy cortos, remolque o caminos de tierra, Toyota pide cambiarlo cada 6 meses.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'fabricante','Plan Toyota','Libro de mantenimiento del Yaris actual: cambio cada 60.000 km o 4 años. Se revisa en cada servicio; con mucho polvo, antes.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Los planes publicados para el Yaris lo cambian cada 30.000 km o 2 años; algunos concesionarios lo cambian cada año. Si huele o sale poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','bujias','Bujías','Cambiar',90000,null,null,false,'fabricante','Plan Toyota','El libro de mantenimiento del Yaris actual dice 90.000 km. Son 3 bujías de iridio; el libro no da plazo en años.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','frenos-liquido','Líquido de frenos','Cambiar',30000,24,null,false,'fabricante','Plan Toyota','Plan Toyota: cambiar cada 2 años o 30.000 km. Absorbe humedad con el tiempo, así que hazlo aunque uses poco el coche.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','refrigerante','Líquido refrigerante','Cambiar',150000,120,null,false,'fabricante','Plan Toyota','Plan Toyota con refrigerante Super Long Life (rosa): primer cambio a los 150.000 km (o 10 años) y después cada 90.000 km. Revisar nivel en cada servicio. El sistema híbrido tiene además un circuito para el inversor con el mismo líquido.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Se miran en cada revisión. Cambiar pastillas con menos de 3 mm de material. En el híbrido duran mucho más porque frena el motor eléctrico; vigila que los discos no se oxiden.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','frenos-traseros','Revisar frenos traseros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Detrás lleva tambor o disco según acabado. Revisar desgaste y ajuste del freno de mano.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','cadena','Cadena de distribución','Sin cambio programado',null,null,null,true,'fabricante','Plan Toyota','El motor M15A-FXE lleva cadena, no correa, y el plan Toyota no tiene cambio programado. Solo hay que revisarla si hace ruido metálico al arrancar en frío.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','valvulas','Holgura de válvulas','Revisar si hace ruido',null,null,null,true,'fabricante','Plan Toyota','Toyota solo pide escuchar si hay ruido de taqués o vibraciones en cada revisión y ajustar si hace falta. No hay ajuste programado.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','filtro-gasolina','Filtro de gasolina','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Va dentro del depósito junto a la bomba y el plan Toyota del Yaris no lo cambia. Solo se toca si falla la bomba.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','caja-cambios','Aceite de la transmisión híbrida','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','La transmisión híbrida no tiene embrague ni cambio de aceite programado conocido; que revisen nivel y fugas cada pocos años. Usa aceite Toyota WS.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','filtro-bateria-hibrida','Filtro del ventilador de la batería híbrida','Limpiar',15000,12,null,false,'aproximado','Plazo aproximado','La toma de aire de la batería híbrida está junto al asiento trasero. Límpiala en cada revisión, más a menudo si llevas perro o mucho polvo: si se tapa, la batería se calienta.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: escape, suspensión, dirección, fuelles de palieres, tubos de freno y de combustible. Toyota lo incluye en sus revisiones, pero no pude leer la tabla con detalle.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar antes del invierno; suele durar 4–6 años. En el híbrido la batería de 12 V es pequeña: si se descarga, el coche no se pone en READY aunque la batería híbrida esté bien.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('toyota-yaris-xp210-15-hybrid-116','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',17);
